shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/test/xchar-test.cc
+++ b/test/xchar-test.cc
@@ -440,6 +440,34 @@ TEST(locale_test, localized_double) {
   EXPECT_EQ(fmt::format(loc, "{:8L}", 1230.0), "   1~230");
 }

+TEST(locale_test, localized_double_alignment) {
+  auto loc = std::locale(std::locale(), new numpunct<char>());
+  auto wloc = std::locale(std::locale(), new numpunct<wchar_t>());
+  const struct {
+    double value;
+    const char* text;
+  } cases[] = {{-119.921, "-119?921"},
+               {2194.139, "2~194?139"},
+               {-57.639, "-57?639"},
+               {-5.980, "-5?980"},
+               {-2.119, "-2?119"},
+               {0.295, "0?295"},
+               {1.295, "1?295"},
+               {-0.295, "-0?295"},
+               {0.0, "0?000"}};
+  for (auto test : cases) {
+    auto text = std::string(test.text);
+    auto padding = 19 - text.size();
+    EXPECT_EQ(std::string(padding, ' ') + text,
+              fmt::format(loc, "{:19.3Lf}", test.value));
+    EXPECT_EQ(text + std::string(padding, ' '),
+              fmt::format(loc, "{:<19.3Lf}", test.value));
+    EXPECT_EQ(std::string(padding / 2, ' ') + text +
+                  std::string(padding - padding / 2, ' '),
+              fmt::format(loc, "{:^19.3Lf}", test.value));
+    EXPECT_EQ(std::wstring(padding, L' ') +
+                  std::wstring(text.begin(), text.end()),
+              fmt::format(wloc, L"{:19.3Lf}", test.value));
+  }
+}
+
